<template>
  <section class="workspace-page today dashboard-page">
    <header class="dashboard-welcome"><DailySlogan /><RouterLink to="/pet" class="dashboard-pet" aria-label="查看我的 AI 宠物"><AIPetAvatar :kind="store.local.pet" :stage="store.pet.stage" /><span>{{ store.pet.stage }} · Lv.{{ store.pet.level }}</span></RouterLink></header>
    <div class="dashboard-toolbar"><RouterLink to="/workspace" class="dashboard-goal"><MobileIcon name="target" :size="16" /><span>{{ goal?.title || '创建你的学习目标' }}</span><MobileIcon name="chevronRight" :size="14" /></RouterLink><button class="icon-button" aria-label="定制首页面板" @click="customizing = true"><MobileIcon name="settings" :size="18" /></button><RouterLink :to="{path:'/workspace',query:{tab:'reminders'}}" class="icon-button" aria-label="通知与复习提醒"><Bell :size="18" /></RouterLink></div>
    <PersonalAgentCard class="dashboard-agent-card" />
    <div v-if="store.loading && !store.loaded" class="dashboard-loading"><MobileSkeleton variant="hero" :count="1" /><MobileSkeleton variant="card" :count="2" /></div>
    <div v-if="store.error" class="m-error" role="alert"><b>学习数据加载失败</b><span>{{ store.error }}</span><button class="m-btn m-btn--ghost m-btn--sm" @click="store.refresh">重试</button></div>
    <p v-if="store.storageError" role="alert" class="m-error">{{ store.storageError }}</p>
    <div v-if="store.workspace" class="dashboard-grid" :class="{'dashboard-grid--default':widgets.map(w=>w.id).join(',')==='default-focus,default-tasks,default-week'}">
      <DashboardWidget v-for="widget in widgets" :key="widget.id" :title="widget.kind==='tasks'&&widget.id==='default-tasks'&&widget.title===widgetCatalog.tasks.title?(store.local.completedOnboarding?'今日任务':'开始你的学习旅程'):widget.title" :eyebrow="widget.kind==='focus'?'留一段时间，学一点新东西':undefined" :source="widgetCatalog[widget.kind].source" :featured="widget.kind==='focus'" :class="[`dashboard-panel--${widget.kind}`,{'today__hero':widget.kind==='focus'&&!!topic,'today__start':widget.kind==='focus'&&!!welcome}]">
        <template #action><span v-if="widget.kind==='focus'" class="focus-duration">{{ runningFocus?.minutes || 25 }}<span>min</span></span><MobileIcon v-else :name="widgetIcons[widget.kind]" :size="18" /></template>
        <template v-if="widget.kind==='focus'"><h3 class="focus-widget-title">{{ (!widget.goalId ? topic?.topicName : null) || (widget.goalId ? goalFor(widget.goalId)?.title : goal?.title) || (welcome ? welcomeFieldLabel(welcome.answers) : '从这 25 分钟开始。') }}</h3><p class="focus-widget-description">{{ topic && !widget.goalId ? `${topic.phaseName} · 来自已保存路径` : welcome ? welcomeGoalLabel(welcome.answers) : '选一个你想弄懂的问题，安静学一会儿。' }}</p><div class="focus-widget-meta"><span><Clock3 :size="16" />{{ runningFocus ? '上次专注可恢复' : '建议专注 25 分钟' }}</span><span><MobileIcon name="check" :size="15" />结束后保留计时</span></div><RouterLink :to="{path:'/focus',query:{...(widget.goalId?{goal:widget.goalId}:topic?{topic:topic.topicId}:{})}}" class="m-btn m-btn--primary m-btn--block">{{ runningFocus ? '继续上次专注' : '开始专注学习 25 分钟' }}<ArrowUpRight :size="18" /></RouterLink><div class="focus-widget-secondary"><button v-if="topic && !widget.goalId" class="m-btn m-btn--ghost m-btn--sm" :disabled="practiceBusy" @click="startPractice">{{ practiceBusy?'正在创建…':'开始练习' }}</button><RouterLink v-if="welcome" :to="{path:'/tutor',query:{welcome:'1'}}">带着目标问导师 →</RouterLink><RouterLink v-else to="/library">打开知识库伴学 →</RouterLink></div><RouterLink v-if="welcome" :to="{path:'/diagnose',query:{welcome:'1'}}" class="workspace-text-action">完善学习计划（选填）</RouterLink><details v-if="topic && !widget.goalId" class="dashboard-recommendation"><summary>为什么推荐这个知识点？</summary><p>{{ topic.reason }}。推荐依据为保存的路径；掌握状态需结合实际练习证据核对。</p></details></template>
        <template v-else-if="widget.kind==='tasks'"><div v-if="!store.local.completedOnboarding" class="onboarding-checklist"><div class="onboarding-heading"><span>完成第一段学习旅程</span><b>{{ onboarding.filter(t=>t.done).length }} / {{ onboarding.length }}</b></div><template v-for="task in onboarding.filter(t=>!t.done)" :key="task.id"><RouterLink v-if="task.to" :to="task.to" class="onboarding-task"><span class="task-empty-dot"/><span><b>{{ task.title }}</b><small>{{ task.condition }}</small></span><ChevronRight :size="16" /></RouterLink><button v-else class="onboarding-task" @click="router.push('/diagnose')"><span class="task-empty-dot"/><span><b>{{ task.title }}</b><small>{{ task.condition }}</small></span><ChevronRight :size="16" /></button></template><button class="workspace-text-action" @click="store.local.completedOnboarding=true;store.persist()">我想先自己探索，收起引导</button></div><template v-else><div v-if="!scopedTasks(widget.goalId).length" class="dashboard-inline-empty"><CheckCircle2 :size="24" /><p>今天没有待确认的新任务</p><RouterLink to="/agent">让星枢帮我拆解目标 →</RouterLink></div><label v-for="task in scopedTasks(widget.goalId).slice(0,5)" :key="task.id" class="workspace-checkbox"><input type="checkbox" :checked="task.done" :disabled="taskBusy===task.id" @change="toggleTask(task)"/><span>{{ task.title }}<small>建议 {{ task.minutes }} 分钟 · 手动确认完成</small></span></label></template></template>
        <template v-else-if="widget.kind==='week'"><WeeklyProgressCard v-if="!store.evidenceError" :goal-id="widget.goalId"/><p v-else class="workspace-caption">{{ store.evidenceError }}<button class="workspace-text-action" @click="store.refresh">重新读取</button></p></template>
        <template v-else-if="widget.kind==='review'&&store.evidenceError"><p class="workspace-caption">{{ store.evidenceError }}</p></template><template v-else-if="widget.kind==='review'&&widget.goalId"><p class="workspace-caption">错题接口尚无目标归属。请在面板设置中改为全部记录，避免混入其他课程。</p></template><template v-else-if="widget.kind==='review'"><div v-if="!store.reviews.length" class="dashboard-inline-empty"><MobileIcon name="check" :size="24" /><p>尚无已完成练习的错题记录</p><RouterLink to="/learn?tab=practice">做一组练习 →</RouterLink></div><RouterLink v-for="row in store.reviews.slice(0,3)" :key="row.exercise.id" to="/review" class="dashboard-list-link"><span><b>{{ row.exercise.knowledgePoint }}</b><small>{{ row.review?`安排在 ${dateLabel(row.review.dueAt)} 复习`:'尚未安排复习' }}</small></span><ChevronRight :size="16"/></RouterLink></template>
        <template v-else-if="widget.kind==='library'&&widget.goalId"><p class="workspace-caption">资料尚未绑定长期目标。请在面板设置中选择全部记录查看私有资料。</p></template><template v-else-if="widget.kind==='library'"><div v-if="!store.workspace.materials.length" class="dashboard-inline-empty"><BookOpen :size="26"/><p>放进第一份讲义，再从原文开始。</p><RouterLink to="/library">导入学习资料 →</RouterLink></div><RouterLink v-for="material in store.workspace.materials.slice(-3).reverse()" :key="material.id" :to="{path:'/library',query:{material:material.id}}" class="dashboard-list-link"><span><b>{{ material.title }}</b><small>{{ material.sections.length }} 段可定位原文</small></span><ChevronRight :size="16"/></RouterLink></template>
        <template v-else-if="widget.kind==='goals'"><RouterLink v-for="item in store.workspace.goals.filter(g=>!widget.goalId||g.id===widget.goalId).slice(0,3)" :key="item.id" to="/workspace" class="dashboard-list-link"><span><b>{{ item.title }}</b><small>{{ item.dailyMinutes }} 分钟 / 天 · {{ dateLabel(item.deadline) }}</small></span><ChevronRight :size="16"/></RouterLink><RouterLink v-if="!store.workspace.goals.length" to="/workspace" class="workspace-text-action">创建第一个学习目标 →</RouterLink></template>
        <template v-else><RouterLink v-for="task in store.workspace.tasks.filter(t=>!widget.goalId||t.goalId===widget.goalId).slice(0,3)" :key="task.id" to="/agent" class="dashboard-list-link"><span><b>{{ task.prompt }}</b><small>{{ taskLabels[task.status] }}</small></span><ChevronRight :size="16"/></RouterLink><RouterLink v-if="!store.workspace.tasks.length" to="/agent" class="workspace-text-action">交给星枢第一件任务 →</RouterLink></template>
      </DashboardWidget>
      <div v-if="!widgets.length" class="workspace-empty"><h2>留一块空间，给自己的工作台</h2><p>所有面板已隐藏或移除，随时可以恢复。</p><button class="m-btn m-btn--primary" @click="customizing=true">管理或恢复面板</button></div>
    </div>
    <div class="dashboard-shortcuts"><RouterLink to="/library"><BookOpen :size="19"/>导入资料</RouterLink><RouterLink to="/review"><RotateCw :size="19"/>错题复习</RouterLink><RouterLink to="/agent"><Sparkles :size="19"/>让星枢帮我</RouterLink><RouterLink to="/learn?tab=plan"><Waypoints :size="19"/>长期学习路径</RouterLink></div>
    <p v-if="actionError" class="m-error" role="alert">{{ actionError }}</p>
    <WidgetCustomizer v-model="customizing" />
  </section>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowUpRight, Bell, BookOpen, CheckCircle2, ChevronRight, Clock3, RotateCw, Sparkles, Waypoints } from 'lucide-vue-next'
import { apiGet } from '@/lib/api'
import { useLearningWorkspace } from '@/mobile/stores/learning-workspace'
import { activeGoal, changeWorkspace, dateLabel, taskLabels } from '@/mobile/data/workspace'
import { welcomeUpdated,welcomeFieldLabel,welcomeGoalLabel,type WelcomeRecord } from '@/mobile/data/welcome'
import { selectTodayTopic } from '@/mobile/data/learning-data'
import { createStudySession } from '@/mobile/data/study'
import { widgetCatalog, type WidgetKind } from '@/mobile/domain/companion'
import AIPetAvatar from '@/mobile/components/AIPetAvatar.vue'
import DailySlogan from '@/mobile/components/DailySlogan.vue'
import DashboardWidget from '@/mobile/components/DashboardWidget.vue'
import WidgetCustomizer from '@/mobile/components/WidgetCustomizer.vue'
import WeeklyProgressCard from '@/mobile/components/WeeklyProgressCard.vue'
import MobileIcon, {type IconName} from '@/mobile/components/MobileIcon.vue'
import MobileSkeleton from '@/mobile/components/MobileSkeleton.vue'
import PersonalAgentCard from '@/mobile/components/PersonalAgentCard.vue'
const store=useLearningWorkspace(),router=useRouter(),customizing=ref(false),welcome=ref<WelcomeRecord|null>(null),practiceBusy=ref(false),taskBusy=ref(''),actionError=ref('')
const widgetIcons:Record<WidgetKind,IconName>={focus:'clock',tasks:'target',week:'chart',review:'refresh',library:'book',goals:'target',agent:'sparkle'}
const widgets=computed(()=>store.local.widgets.filter(w=>w.visible)),goal=computed(()=>activeGoal(store.workspace)),topic=computed(()=>selectTodayTopic(store.path)),runningFocus=computed(()=>store.workspace?.focus.find(f=>f.status==='running'||f.status==='paused'))
const onboarding=computed(()=>[{id:'goal',title:'定一个学习目标',condition:'保存目标与每天可用时间',to:'/workspace',done:!!store.workspace?.goals.length},{id:'source',title:'导入第一份资料',condition:'保存一份可读取的讲义或笔记',to:'/library',done:!!store.workspace?.materials.some(m=>m.status==='ready')},{id:'baseline',title:'确认自己的学习起点',condition:'完成自评或第一次真实练习',to:'/diagnose',done:!!store.profile||store.events.some(e=>e.type==='session-complete')},{id:'focus',title:'完成一次有效专注',condition:'完成至少 80% 计时且不少于 1 分钟',to:'/focus',done:!!store.workspace?.focus.some(f=>f.status==='completed'&&f.accumulatedSeconds>=60&&f.accumulatedSeconds>=f.minutes*60*.8)}])
watch(onboarding,list=>{if(list.every(t=>t.done)&&!store.local.completedOnboarding){store.local.completedOnboarding=true;store.persist()}},{deep:true})
async function loadWelcome(){try{const record=await apiGet<{result:WelcomeRecord|null}>('/api/account/onboarding');welcome.value=record.result?.status==='completed'?record.result:null}catch{welcome.value=null}}
watch(welcomeUpdated,loadWelcome)
onMounted(async()=>{await store.refresh();await loadWelcome()})
function goalFor(id:string){return store.workspace?.goals.find(g=>g.id===id)}
function scopedTasks(goalId:string|null){return store.taskItems.filter(t=>!goalId||t.goalId===goalId)}
async function toggleTask(task:{id:string;taskId:string;done:boolean}){taskBusy.value=task.id;try{await changeWorkspace('checklist',{id:task.id,taskId:task.taskId,done:!task.done});await store.refresh()}catch(e){actionError.value=e instanceof Error?e.message:'保存失败'}finally{taskBusy.value=''}}
async function startPractice(){if(!topic.value||practiceBusy.value)return;practiceBusy.value=true;try{const result=await createStudySession([topic.value.topicId],3);if('error'in result)throw new Error(result.message);await router.push(`/study/session/${result.session.id}`)}catch(e){actionError.value=e instanceof Error?e.message:'创建失败'}finally{practiceBusy.value=false}}
</script>
<style scoped>.dashboard-welcome{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:8px;align-items:center;margin:2px 0 12px}.dashboard-pet{display:grid;justify-items:center;text-decoration:none;color:var(--m-text-faint);align-self:start}.dashboard-pet .ai-pet-avatar{width:125px}.dashboard-pet>span{font-size:11px;margin-top:-8px}.dashboard-toolbar{display:flex;align-items:center;gap:8px;margin-bottom:24px}.dashboard-goal{display:flex;align-items:center;gap:8px;min-height:44px;min-width:0;flex:1;color:var(--m-text-dim);text-decoration:none;font-size:13px}.dashboard-goal span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:18px}.focus-widget-title{font-size:25px;line-height:1.5;letter-spacing:-.6px;margin:0 0 10px}.focus-widget-description{font-size:14px;line-height:1.8;color:var(--m-text-dim);margin:0 0 20px}.focus-widget-meta{display:flex;flex-wrap:wrap;gap:8px 16px;font-size:12px;color:var(--m-text-faint);margin-bottom:20px}.focus-widget-meta span{display:flex;align-items:center;gap:6px}.dashboard-widget .m-btn--primary{justify-content:space-between;font-size:15px}.focus-widget-secondary{display:flex;align-items:center;gap:14px;justify-content:space-between;margin-top:12px;flex-wrap:wrap}.focus-widget-secondary>a{font-size:13px;text-decoration:none;color:var(--m-primary);min-height:40px;display:flex;align-items:center}.dashboard-recommendation{margin-top:12px;border-top:1px solid var(--m-border);font-size:12px;color:var(--m-text-faint)}.dashboard-recommendation summary{cursor:pointer;min-height:40px;display:flex;align-items:center}.dashboard-recommendation p{line-height:1.8;margin:0}.onboarding-heading{display:flex;justify-content:space-between;gap:12px;font-size:13px;color:var(--m-text-faint);margin-bottom:8px}.onboarding-heading b{color:var(--m-primary);font-weight:500}.onboarding-task{display:flex;align-items:center;gap:12px;padding:14px 0;border:0;border-bottom:1px solid var(--m-border);background:none;width:100%;text-align:left;text-decoration:none;color:var(--m-text);font:inherit;cursor:pointer}.onboarding-task>span:nth-child(2){flex:1;min-width:0}.task-empty-dot{width:18px;height:18px;border:1px solid var(--m-border-strong);border-radius:6px;flex:none}.onboarding-task b{font-size:14px;font-weight:500}.onboarding-task small{display:block;font-size:12px;line-height:1.7;color:var(--m-text-faint);margin-top:5px}.dashboard-inline-empty{text-align:center;color:var(--m-text-faint);font-size:14px;padding:20px 0;line-height:1.8}.dashboard-inline-empty a{color:var(--m-primary);min-height:44px;display:inline-flex;align-items:center;text-decoration:none}.dashboard-list-link{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid var(--m-border);color:var(--m-text);text-decoration:none}.dashboard-list-link b{font-size:14px;font-weight:500;line-height:1.7}.dashboard-list-link small{display:block;margin-top:5px;color:var(--m-text-faint);font-size:12px}.dashboard-shortcuts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:22px}.dashboard-shortcuts a{display:flex;gap:9px;align-items:center;padding:14px;border:1px solid var(--m-border);border-radius:14px;min-height:48px;text-decoration:none;color:var(--m-text-dim);font-size:13px;background:var(--m-surface)}.dashboard-shortcuts svg{color:var(--m-primary)}@media(min-width:760px){.dashboard-welcome{grid-template-columns:minmax(0,1fr) 180px}.dashboard-pet .ai-pet-avatar{width:180px}.dashboard-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-panel--week{grid-column:1/-1}.dashboard-shortcuts{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(min-width:1300px){.dashboard-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.dashboard-panel--focus{grid-column:span 2}.dashboard-panel--week{grid-column:auto}.dashboard-shortcuts{max-width:100%}}@media(max-width:359px){.dashboard-welcome{grid-template-columns:minmax(0,1fr) 80px}.dashboard-pet .ai-pet-avatar{width:98px}.dashboard-pet>span{font-size:10px}}@media(min-width:1300px){.dashboard-grid{grid-template-columns:1.12fr 1fr 1fr;align-items:start}.dashboard-panel--focus{grid-column:auto}}
</style>
<style scoped>.dashboard-agent-card{margin:0 0 18px}</style>
